import json
word = [1, 0, 2, 0, 2, 3]
answers = [3, 2, 3, 2, 3]
def gamma(prefix):
    pend = []
    for s in prefix:
        if s < 2:
            pend.append(s)
        else:
            pend.pop()
    return pend[-1]
omega = {}
for t in range(5):
    omega[gamma(word[:t + 1])] = answers[t]
print(json.dumps({"omega0": omega[0], "omega1": omega[1]}))
